Deno.serve(() => Response.json(
  { success: false, error: 'Emergency admin bootstrap sign-in has been retired.' },
  { status: 410 },
));

import { createClientFromRequest } from 'npm:@base44/sdk@0.8.25';
import { authenticateSignShopSession } from '../../shared/signShopSession.ts';

/**
 * Manifest mapping legacy public asset paths ("/fleet-assets/x.jpg",
 * "/permitting-evidence/y.pdf") to file-storage URLs.
 * - get_manifest: PUBLIC — these assets were already public static files
 *   (fleet QR public reports, permitting evidence links), so exposing the
 *   map preserves that visibility.
 * - save_manifest: admin session only — replaces the whole map.
 */
const SETTING_KEY = 'hostedAssetManifest';
const MAX_ENTRIES = 500;
const MAX_PATH = 400;
const MAX_URL = 1200;

const bad = (msg, status = 400) => Response.json({ error: msg }, { status });

async function loadManifest(base44) {
  const rows = await base44.asServiceRole.entities.GlobalSettings.filter({ setting_key: SETTING_KEY });
  const row = Array.isArray(rows) && rows[0];
  let manifest = {};
  try { manifest = row?.setting_value ? JSON.parse(row.setting_value) : {}; } catch { manifest = {}; }
  return { row, manifest };
}

Deno.serve(async (req) => {
  try {
    const base44 = createClientFromRequest(req);
    const body = await req.json().catch(() => ({}));
    const op = String(body?.op || 'get_manifest');

    if (op === 'get_manifest') {
      const { manifest } = await loadManifest(base44);
      return Response.json({ manifest, count: Object.keys(manifest).length });
    }

    if (op === 'save_manifest') {
      const actor = await authenticateSignShopSession(base44, body?.session_token).catch(() => null);
      if (actor?.role !== 'admin') return bad('Forbidden: Admin access required', 403);

      const incoming = body?.manifest;
      if (!incoming || typeof incoming !== 'object' || Array.isArray(incoming)) {
        return bad('manifest must be an object mapping paths to URLs');
      }
      const entries = Object.entries(incoming);
      if (entries.length > MAX_ENTRIES) return bad(`manifest exceeds ${MAX_ENTRIES} entries`);
      const clean = {};
      for (const [k, v] of entries) {
        const path = String(k || '').trim();
        const url = String(v || '').trim();
        if (!path.startsWith('/') || path.length > MAX_PATH || path.includes('..')) return bad(`invalid path: ${path.slice(0, 60)}`);
        if (!/^https:\/\//.test(url) || url.length > MAX_URL) return bad(`invalid URL for ${path.slice(0, 60)}`);
        clean[path] = url;
      }

      const { row } = await loadManifest(base44);
      const value = JSON.stringify(clean);
      if (row?.id) {
        await base44.asServiceRole.entities.GlobalSettings.update(row.id, { setting_value: value });
      } else {
        await base44.asServiceRole.entities.GlobalSettings.create({ setting_key: SETTING_KEY, setting_value: value });
      }
      return Response.json({ saved: true, count: entries.length });
    }

    return bad('Unknown op');
  } catch (error) {
    console.error('hostedAssetManifest error:', error?.message || error);
    return Response.json({ error: 'Manifest operation failed' }, { status: 500 });
  }
});

import { authenticateSignShopSession } from '../../shared/signShopSession.ts';
import { createClientFromRequest } from 'npm:@base44/sdk@0.8.25';

Deno.serve(async (request: Request) => {
  try {
    const base44 = createClientFromRequest(request);
    const body = await request.json().catch(() => ({}));
    const actor = await authenticateSignShopSession(base44, body?.session_token);
    const requests = base44.asServiceRole.entities.AccessRequest;
    const audit = base44.asServiceRole.entities.AdminAuditLog;
    const action = body?.action || 'submit';

    if (action === 'submit') {
      const reason = String(body?.reason || '').trim().slice(0, 500);
      const sections = Array.isArray(body?.requested_sections)
        ? body.requested_sections.map((v: unknown) => String(v).slice(0, 80)).filter(Boolean).slice(0, 20)
        : [];
      // Reason keywords map to grant types — 'breakglass' asks for a 4-hour
      // time-boxed grant, 'full admin' asks for the complete role.
      const reasonLower = reason.toLowerCase();
      if (reasonLower.includes('breakglass') && !sections.includes('breakglass')) sections.push('breakglass');
      if (reasonLower.includes('full admin') && !sections.includes('full_admin')) sections.push('full_admin');
      // Admins may propose a grant for someone else (two-admin flow):
      // target_email receives the grant; actor is recorded as proposer and
      // cannot approve their own full_admin/breakglass proposal.
      const targetEmail = String(body?.target_email || '').trim().toLowerCase();
      const requesterEmail = targetEmail && actor.role === 'admin' ? targetEmail : actor.email;
      const existing = await requests.filter({ requester_email: requesterEmail, status: 'pending' });
      if (Array.isArray(existing) && existing.length > 0) {
        return Response.json({ success: true, already_pending: true });
      }
      const row = await requests.create({
        requester_email: requesterEmail, requested_sections: sections, reason,
        proposer_email: actor.email,
        status: 'pending',
      });
      await audit.create({ actor_email: actor.email, action: 'request_access', target_email: actor.email, detail: reason ? `${sections.join(',')} — ${reason}` : sections.join(','), at: new Date().toISOString() });
      return Response.json({ success: true, id: row.id });
    }

    if (actor.role !== 'admin') {
      return Response.json({ success: false, error: 'Admin access required' }, { status: 403 });
    }

    if (action === 'list') {
      const rows = await requests.filter({ status: 'pending' }, '-created_date', 50);
      return Response.json({ success: true, requests: rows || [] });
    }

    if (action === 'approve' || action === 'reject') {
      const id = String(body?.request_id || '');
      if (!id) return Response.json({ success: false, error: 'request_id required' }, { status: 400 });
      const row = await requests.get(id).catch(() => null);
      if (!row) return Response.json({ success: false, error: 'Request not found' }, { status: 404 });
      if (row.status !== 'pending') return Response.json({ success: false, error: 'Request already decided' }, { status: 409 });
      const note = String(body?.note || '').trim().slice(0, 300);
      // Approving applies the grant: 'full_admin' → full admin, 'breakglass'
      // → full admin for 4 hours (auto-lapses via admin_grant_expires),
      // otherwise sections merge into admin_permissions.sections. Only the
      // requester's record is written — the approver's access never changes.
      const sections0 = Array.isArray(row.requested_sections) ? row.requested_sections : [];
      const needsSecondAdmin = sections0.includes('full_admin') || sections0.includes('breakglass');
      if (needsSecondAdmin && row.proposer_email && String(row.proposer_email).toLowerCase() === String(actor.email).toLowerCase()) {
        return Response.json({ success: false, error: 'Two-admin rule: a different admin must approve full-admin and break-glass grants.' }, { status: 403 });
      }
      if (action === 'approve') {
        const users = base44.asServiceRole.entities.AuthorizedEmail;
        const targetRows = await users.filter({ email: row.requester_email });
        if (!Array.isArray(targetRows) || targetRows.length !== 1) {
          return Response.json({ success: false, error: 'Requesting user could not be resolved' }, { status: 404 });
        }
        const target = targetRows[0];
        const sections = Array.isArray(row.requested_sections) ? row.requested_sections : [];
        const next: Record<string, unknown> = { role: 'admin' };
        if (sections.includes('breakglass')) {
          next.is_full_admin = true;
          next.admin_grant_expires = new Date(Date.now() + 4 * 60 * 60 * 1000).toISOString();
        } else if (sections.includes('full_admin')) {
          next.is_full_admin = true;
        } else if (sections.length) {
          const perms = target.admin_permissions && typeof target.admin_permissions === 'object' ? target.admin_permissions : {};
          next.admin_permissions = { ...perms, sections: [...new Set([...(Array.isArray(perms.sections) ? perms.sections : []), ...sections])] };
        }
        await users.update(target.id, next);
      }
      await requests.update(id, {
        status: action === 'approve' ? 'approved' : 'rejected',
        reviewer_email: actor.email, decided_at: new Date().toISOString(), decided_note: note,
      });
      await audit.create({ actor_email: actor.email, action: `${action}_access`, target_email: row.requester_email, detail: note, at: new Date().toISOString() });
      return Response.json({ success: true });
    }

    return Response.json({ success: false, error: 'Unknown action' }, { status: 400 });
  } catch (e: any) {
    return Response.json({ success: false, error: e?.message || 'Access request failed' }, { status: e?.status || 500 });
  }
});

import { createClientFromRequest } from 'npm:@base44/sdk@0.8.25';
import { replaceAuthorizedEmailCredentialFieldsIfUnchanged } from '../../shared/authorizedEmailCredentialPersistence.mjs';
import { hashBearerToken } from '../../shared/bearerTokenHash.ts';
import { authenticateSignShopSession } from '../../shared/signShopSession.ts';

import { processWorkflowTriggerEvent } from '../../shared/workflowTriggerEngine.ts';

// Fire-and-forget automation emit — a failure must never break a verified
// write, so this swallows and logs like the other emit helpers.
async function emitRecordAutomation(base44: any, eventType: string, recordId: string, actor: string) {
  try {
    await processWorkflowTriggerEvent({
      base44,
      payload: { event_type: eventType, record: { id: recordId } },
      changedByOverride: actor,
    });
  } catch (error: any) {
    console.error(`Automation emit failed for ${eventType}:`, error?.message || error);
  }
}

function secureToken() {
  const bytes = new Uint8Array(32);
  crypto.getRandomValues(bytes);
  return Array.from(bytes, (value) => value.toString(16).padStart(2, '0')).join('');
}

function htmlEscape(value: unknown) {
  return String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

Deno.serve(async (req) => {
  try {
    const base44 = createClientFromRequest(req);
    const body = await req.json().catch(() => ({}));
    const sessionToken = String(body?.session_token || '').trim();
    const requestedEmail = String(body?.target_email || '').trim().toLowerCase();
    const authorized = base44.asServiceRole.entities.AuthorizedEmail;

    let actor;
    try {
      actor = await authenticateSignShopSession(base44, sessionToken);
    } catch (authError) {
      const status = Number(authError?.status || 401);
      const safeStatus = [401, 409, 429, 503].includes(status) ? status : 401;
      const error = safeStatus === 503
        ? 'Session authentication is unavailable'
        : safeStatus === 409
          ? 'Signed-in user identity could not be verified'
          : 'A valid signed-in session is required';
      return Response.json({ success: false, error }, { status: safeStatus });
    }

    const actorEmail = String(actor.email || '').trim().toLowerCase();
    const targetEmail = requestedEmail || actorEmail;
    if (!targetEmail) {
      return Response.json({ success: false, error: 'Target email is required' }, { status: 400 });
    }
    if (targetEmail !== actorEmail && actor.role !== 'admin') {
      return Response.json({ success: false, error: 'Admin access is required to reset another user' }, { status: 403 });
    }

    const targetRows = await authorized.filter({ email: targetEmail });
    if (!Array.isArray(targetRows) || targetRows.length !== 1) {
      return Response.json({
        success: false,
        error: Array.isArray(targetRows) && targetRows.length === 0 ? 'Authorized user not found' : 'Authorized user identity is ambiguous',
      }, { status: Array.isArray(targetRows) && targetRows.length === 0 ? 404 : 409 });
    }
    const target = targetRows[0];

    // Cooldown: if an unexpired reset token was already issued, don't mint a
    // new one (or resend email) — rapid repeated requests are email bombing.
    const existingExpiry = Date.parse(String(target?.password_reset_expires || '')) || 0;
    if (existingExpiry > Date.now()) {
      return Response.json({ success: true, cooldown: true, message: 'A reset link was already issued recently — check your email or wait for it to expire before requesting another.' });
    }

    const resetToken = secureToken();
    const resetTokenHash = await hashBearerToken(resetToken);
    const expires = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString();
    await replaceAuthorizedEmailCredentialFieldsIfUnchanged({
      entity: authorized,
      user: target,
      nextFields: {
        password_reset_token: null,
        password_reset_token_hash: resetTokenHash,
        password_reset_expires: expires,
      },
      guardFields: { email: target.email },
      label: `Password reset token for ${target.email}`,
    });

    const appUrl = String(Deno.env.get('PUBLIC_APP_URL') || 'https://clay-flow-signage-suite-387da97c.base44.app').replace(/\/$/, '');
    const resetLink = `${appUrl}/ResetPassword?token=${encodeURIComponent(resetToken)}`;
    const displayName = htmlEscape(target.full_name || target.email || 'there');
    const emailBody = `
      <div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;padding:20px;color:#1F2937;">
        <div style="background:#FFFFFF;padding:30px;border-radius:16px;border:1px solid #E5E7EB;">
          <h2 style="margin:0 0 16px 0;">Password Reset</h2>
          <p>Hello ${displayName},</p>
          <p>A password reset was requested for your Sign Shop Workflow account.</p>
          <p style="text-align:center;margin:30px 0;">
            <a href="${resetLink}" style="background-color:#7C3AED;color:#FFFFFF;padding:14px 28px;border-radius:8px;text-decoration:none;display:inline-block;font-weight:bold;">Reset Password</a>
          </p>
          <p style="color:#6B7280;font-size:14px;">This one-time link expires in 24 hours. If you did not request it, you can ignore this email.</p>
        </div>
      </div>`;

    const sendResponse = await base44.asServiceRole.functions.invoke('sendGmail', {
      to: target.email,
      subject: 'Reset Your Sign Shop Workflow Password',
      body: emailBody,
      _workflow_capability: 'ccs-sendGmail-internal-svc-cap-791d5baab4d78cfc',
    });
    const sendResult = sendResponse?.data || sendResponse;
    if (sendResult?.error || sendResult?.success === false) {
      console.error('Password reset email could not be sent for user id:', target.id);
      return Response.json({ success: false, error: 'The reset token was saved, but the reset email could not be sent. Retry to issue a new link.' }, { status: 502 });
    }

    await emitRecordAutomation(base44, 'user_password_reset', target.id, actorEmail);
    return Response.json({ success: true });
  } catch (error) {
    console.error('issuePasswordReset error:', error?.message || error);
    return Response.json({ success: false, error: 'Password reset could not be issued safely' }, { status: 500 });
  }
});

import { createClientFromRequest } from 'npm:@base44/sdk@0.8.25';
import bcrypt from 'npm:bcryptjs@2.4.3';
import { hashBearerToken } from '../../shared/bearerTokenHash.ts';
import { authenticateSignShopSession } from '../../shared/signShopSession.ts';
import {
  claimPasswordResetToken,
  replaceAuthorizedEmailCredentialFieldsIfUnchanged,
} from '../../shared/authorizedEmailCredentialPersistence.mjs';

Deno.serve(async (req) => {
  try {
    const body = await req.json();
    const { username, new_password, user_email, reset_token, session_token } = body || {};

    if (!new_password || new_password.length < 8) {
      return Response.json({ success: false, error: 'Password must be at least 8 characters' }, { status: 400 });
    }

    const base44 = createClientFromRequest(req);
    const authorized = base44.asServiceRole.entities.AuthorizedEmail;

    let targetUser = null;
    let isResetFlow = false;

    if (reset_token) {
      const resetTokenHash = await hashBearerToken(reset_token);
      let users = await authorized.filter({ password_reset_token_hash: resetTokenHash });
      if (Array.isArray(users) && users.length === 0) {
        // Backward-compatible rollout guard for a legacy raw token issued by an
        // older deployed function immediately before hash-at-rest became active.
        users = await authorized.filter({ password_reset_token: reset_token });
      }
      if (!Array.isArray(users) || users.length !== 1) {
        return Response.json({ success: false, error: 'Invalid or already-used reset link' }, { status: 401 });
      }
      const candidate = users[0];
      if (candidate.password_reset_expires && new Date(candidate.password_reset_expires) < new Date()) {
        return Response.json({ success: false, error: 'Reset link expired' }, { status: 401 });
      }
      try {
        targetUser = await claimPasswordResetToken({
          entity: authorized,
          user: candidate,
          resetToken: reset_token,
          resetTokenHash,
          label: `Password reset token for ${candidate.email}`,
        });
      } catch (claimError) {
        console.error('Password reset token claim failed:', claimError?.message || claimError);
        return Response.json({
          success: false,
          error: 'This password reset link could not be claimed safely. Request a new reset link.',
        }, { status: 409 });
      }
      isResetFlow = true;
    } else {
      let admin;
      try {
        admin = await authenticateSignShopSession(base44, session_token);
      } catch (authError) {
        const status = Number(authError?.status || 401);
        const safeStatus = [401, 409, 429, 503].includes(status) ? status : 401;
        const error = safeStatus === 503
          ? 'Session authentication is unavailable'
          : safeStatus === 409
            ? 'Admin authentication could not be verified'
            : 'Admin authentication required';
        return Response.json({ success: false, error }, { status: safeStatus });
      }
      if (admin?.role !== 'admin') {
        return Response.json({ success: false, error: 'Admin authentication required' }, { status: 403 });
      }
      const lookupEmail = (user_email || '').toLowerCase().trim();
      if (!lookupEmail) {
        return Response.json({ success: false, error: 'user_email required' }, { status: 400 });
      }
      const users = await authorized.filter({ email: lookupEmail });
      if (!users || users.length !== 1) {
        return Response.json({ success: false, error: users?.length > 1 ? 'Duplicate authorized user records require admin review' : 'User not found' }, { status: users?.length > 1 ? 409 : 404 });
      }
      targetUser = users[0];
    }

    const uname = (username || targetUser.username || targetUser.email.split('@')[0]).toLowerCase().trim();
    if (!uname) {
      return Response.json({ success: false, error: 'Username required' }, { status: 400 });
    }
    const usernameMatches = await authorized.filter({ username: uname });
    if ((usernameMatches || []).some(row => row.id !== targetUser.id)) {
      return Response.json({ success: false, error: 'Username is already in use' }, { status: 409 });
    }

    const password_hash = await bcrypt.hash(new_password, 10);
    const nextFields: Record<string, unknown> = {
      username: uname,
      password_hash,
      password_changed_at: new Date().toISOString(),
      force_password_reset: false,
      session_not_before: new Date().toISOString(),
      // A credential change is also the recovery path out of a brute-force
      // lockout; leaving the deadline in place would keep the new password
      // refused until it lapses.
      failed_login_count: 0,
      login_locked_until: null,
    };
    // Admin password changes invalidate any outstanding reset link. Reset-flow links
    // were already claimed atomically above.
    if (!isResetFlow) {
      nextFields.password_reset_token = null;
      nextFields.password_reset_token_hash = null;
      nextFields.password_reset_expires = null;
    }

    await replaceAuthorizedEmailCredentialFieldsIfUnchanged({
      entity: authorized,
      user: targetUser,
      nextFields,
      guardFields: { email: targetUser.email },
      label: `Password update for ${targetUser.email}`,
    });

    return Response.json({ success: true });
  } catch (error) {
    console.error('setPassword error:', error);
    return Response.json({ success: false, error: 'Password update could not be completed safely' }, { status: 500 });
  }
});

import { createClientFromRequest } from 'npm:@base44/sdk@0.8.25';
import bcrypt from 'npm:bcryptjs@2.4.3';
import { replaceAuthorizedEmailCredentialFieldsIfUnchanged } from '../../shared/authorizedEmailCredentialPersistence.mjs';
import { hashBearerToken } from '../../shared/bearerTokenHash.ts';
import { authenticateSignShopSession } from '../../shared/signShopSession.ts';

import { processWorkflowTriggerEvent } from '../../shared/workflowTriggerEngine.ts';

// Fire-and-forget automation emit — a failure must never break a verified
// write, so this swallows and logs like the other emit helpers.
async function emitRecordAutomation(base44: any, eventType: string, recordId: string, actor: string) {
  try {
    await processWorkflowTriggerEvent({
      base44,
      payload: { event_type: eventType, record: { id: recordId } },
      changedByOverride: actor,
    });
  } catch (error: any) {
    console.error(`Automation emit failed for ${eventType}:`, error?.message || error);
  }
}

function secureToken() {
  const bytes = new Uint8Array(32);
  crypto.getRandomValues(bytes);
  return Array.from(bytes, value => value.toString(16).padStart(2, '0')).join('');
}
function sanitizedUser(user: any) {
  if (!user?.id) return null;
  return {
    id: user.id,
    email: user.email || '',
    full_name: user.full_name || '',
    username: user.username || '',
    role: user.role || 'user',
    sales_roles: Array.isArray(user.sales_roles) ? user.sales_roles : [],
    can_import_export: user.can_import_export === true,
    can_view_resources: user.can_view_resources === true,
    face_descriptors: Array.isArray(user.face_descriptors) ? user.face_descriptors : [],
    hr_data: user.hr_data && typeof user.hr_data === 'object' && !Array.isArray(user.hr_data) ? user.hr_data : {},
    onboarding_complete: user.onboarding_complete === true,
    updated_date: user.updated_date || '',
  };
}
async function loadInvitation(entity: any, token: string) {
  const cleanToken = String(token || '').trim();
  if (!cleanToken) throw Object.assign(new Error('Onboarding token is required'), { status: 400 });
  const tokenHash = await hashBearerToken(cleanToken);
  let rows = await entity.filter({ onboarding_token_hash: tokenHash });
  if (!Array.isArray(rows)) throw Object.assign(new Error('Onboarding token lookup could not be verified'), { status: 503 });
  let tokenGuard: Record<string, unknown> = { onboarding_token_hash: tokenHash };
  if (rows.length === 0) {
    // Backward-compatible rollout guard for a legacy raw invitation issued by
    // an older deployed function immediately before hash-at-rest became active.
    rows = await entity.filter({ onboarding_token: cleanToken });
    if (!Array.isArray(rows)) throw Object.assign(new Error('Onboarding token lookup could not be verified'), { status: 503 });
    tokenGuard = { onboarding_token: cleanToken };
  }
  if (rows.length !== 1) throw Object.assign(new Error(rows.length ? 'Onboarding identity is ambiguous' : 'This onboarding link is invalid or already used'), { status: rows.length ? 409 : 401 });
  const user = rows[0];
  if (user.onboarding_complete === true) throw Object.assign(new Error('This onboarding link has already been completed'), { status: 409 });
  if (user.onboarding_expires && new Date(user.onboarding_expires).getTime() < Date.now()) {
    throw Object.assign(new Error('This onboarding link has expired'), { status: 401 });
  }
  return { user, tokenGuard };
}
function invitationUrl(token: string) {
  const appUrl = String(Deno.env.get('PUBLIC_APP_URL') || 'https://clay-flow-signage-suite-387da97c.base44.app').replace(/\/$/, '');
  return `${appUrl}/NewUserSetup?token=${encodeURIComponent(token)}`;
}

Deno.serve(async (req) => {
  try {
    const base44 = createClientFromRequest(req);
    const body = await req.json().catch(() => ({}));
    const action = String(body?.action || '').trim();
    const authorized = base44.asServiceRole.entities.AuthorizedEmail;

    if (action === 'issue_invite') {
      let actor;
      try {
        actor = await authenticateSignShopSession(base44, body?.session_token);
      } catch (authError) {
        const status = Number(authError?.status || 401);
        const safeStatus = [401, 409, 429, 503].includes(status) ? status : 401;
        const error = safeStatus === 503
          ? 'Session authentication is unavailable'
          : safeStatus === 409
            ? 'Admin authentication could not be verified'
            : 'Admin authentication required';
        return Response.json({ success: false, error }, { status: safeStatus });
      }
      if (actor?.role !== 'admin') {
        return Response.json({ success: false, error: 'Admin authentication required' }, { status: 403 });
      }
      const targetEmail = String(body?.target_email || '').trim().toLowerCase();
      if (!targetEmail) return Response.json({ success: false, error: 'Target email is required' }, { status: 400 });
      const targets = await authorized.filter({ email: targetEmail });
      if (!Array.isArray(targets) || targets.length !== 1) {
        return Response.json({ success: false, error: Array.isArray(targets) && targets.length === 0 ? 'Authorized user not found' : 'Authorized user identity is ambiguous' }, { status: Array.isArray(targets) && targets.length === 0 ? 404 : 409 });
      }
      const target = targets[0];
      const token = secureToken();
      const tokenHash = await hashBearerToken(token);
      const expires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString();
      await replaceAuthorizedEmailCredentialFieldsIfUnchanged({
        entity: authorized,
        user: target,
        nextFields: { onboarding_token: null, onboarding_token_hash: tokenHash, onboarding_expires: expires, onboarding_complete: false },
        guardFields: { email: target.email },
        label: `Onboarding invitation for ${target.email}`,
      });

      const registrationLink = invitationUrl(token);
      const firstName = String(target.full_name || '').trim().split(/\s+/)[0] || 'there';
      let subject = 'Complete Your Sign Shop Workflow Registration';
      let html = `<div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;padding:20px;color:#1F2937;"><div style="background:#FFFFFF;padding:30px;border-radius:16px;border:1px solid #E5E7EB;"><h2>Welcome to Sign Shop Workflow</h2><p>Hi ${firstName.replace(/[<>&"']/g, '')},</p><p>Complete your registration using the button below.</p><p style="text-align:center;margin:30px 0;"><a href="${registrationLink}" style="background-color:#7C3AED;color:#FFFFFF;padding:16px 32px;border-radius:8px;text-decoration:none;display:inline-block;font-weight:bold;">Complete Registration</a></p><p style="color:#6B7280;font-size:14px;">This link expires in 7 days.</p></div></div>`;
      try {
        const aiEmail = await base44.asServiceRole.integrations.Core.InvokeLLM({
          prompt: `Create a brief, professional HTML invitation email for Sign Shop Workflow. Recipient first name: ${firstName}. Role: ${target.role === 'admin' ? 'Admin' : 'Team Member'}. The registration link MUST be used exactly as provided: ${registrationLink}. Use a white background, dark text, a solid #7C3AED CTA button with white text, inline CSS, no emojis, and mention the link expires in 7 days. Return subject and body.`,
          response_json_schema: {
            type: 'object',
            properties: { subject: { type: 'string' }, body: { type: 'string' } },
            required: ['subject', 'body'],
          },
        });
        if (aiEmail?.subject && aiEmail?.body && String(aiEmail.body).includes(registrationLink)) {
          subject = aiEmail.subject;
          html = aiEmail.body;
        }
      } catch (aiError) {
        console.error('Onboarding invitation AI formatting failed; using safe fallback for user id:', target.id);
      }
      const sent = await base44.asServiceRole.functions.invoke('sendGmail', { to: target.email, subject, body: html, _workflow_capability: 'ccs-sendGmail-internal-svc-cap-9f3a7e2b1c4d' });
      const sendResult = sent?.data || sent;
      if (sendResult?.error || sendResult?.success === false) {
        console.error('Onboarding invitation email failed for user id:', target.id);
        return Response.json({ success: false, error: 'The invitation token was saved, but the email could not be sent. Retry to issue a new link.' }, { status: 502 });
      }
      return Response.json({ success: true });
    }

    const token = String(body?.token || '').trim();
    const invitation = await loadInvitation(authorized, token);
    const user = invitation.user;
    const invitationTokenGuard = invitation.tokenGuard;

    if (action === 'validate') {
      return Response.json({ success: true, user: sanitizedUser(user) });
    }

    if (action === 'save_credentials') {
      const fullName = String(body?.full_name || '').trim();
      const username = String(body?.username || '').trim().toLowerCase();
      const password = String(body?.password || '');
      if (!fullName) return Response.json({ success: false, error: 'Full name is required' }, { status: 400 });
      if (!/^[a-z0-9]{3,}$/.test(username)) return Response.json({ success: false, error: 'Username must be at least 3 letters/numbers with no spaces' }, { status: 400 });
      if (password.length < 8) return Response.json({ success: false, error: 'Password must be at least 8 characters' }, { status: 400 });
      const usernameRows = await authorized.filter({ username });
      if (!Array.isArray(usernameRows)) return Response.json({ success: false, error: 'Username uniqueness could not be verified' }, { status: 503 });
      if (usernameRows.some((row: any) => row.id !== user.id)) return Response.json({ success: false, error: 'This username is already in use' }, { status: 409 });

      const nextFields: Record<string, unknown> = {
        full_name: fullName,
        username,
        password_hash: await bcrypt.hash(password, 10),
        password_changed_at: new Date().toISOString(),
        password_reset_token: null,
        password_reset_token_hash: null,
        password_reset_expires: null,
        session_not_before: new Date().toISOString(),
        failed_login_count: 0,
        login_locked_until: null,
      };
      if (Array.isArray(body?.face_descriptors) && body.face_descriptors.length) nextFields.face_descriptors = body.face_descriptors;
      const saved = await replaceAuthorizedEmailCredentialFieldsIfUnchanged({
        entity: authorized,
        user,
        nextFields,
        guardFields: { ...invitationTokenGuard, onboarding_complete: false, email: user.email },
        label: `Onboarding credentials for ${user.email}`,
      });
      return Response.json({ success: true, user: sanitizedUser(saved) });
    }

    if (action === 'save_hr') {
      const hrData = body?.hr_data;
      if (!hrData || typeof hrData !== 'object' || Array.isArray(hrData)) return Response.json({ success: false, error: 'HR data must be an object' }, { status: 400 });
      const saved = await replaceAuthorizedEmailCredentialFieldsIfUnchanged({
        entity: authorized,
        user,
        nextFields: { hr_data: hrData },
        guardFields: { ...invitationTokenGuard, onboarding_complete: false, email: user.email },
        label: `Onboarding HR data for ${user.email}`,
      });
      return Response.json({ success: true, user: sanitizedUser(saved) });
    }

    if (action === 'complete') {
      const saved = await replaceAuthorizedEmailCredentialFieldsIfUnchanged({
        entity: authorized,
        user,
        nextFields: { onboarding_complete: true, onboarding_token: null, onboarding_token_hash: null, onboarding_expires: null },
        guardFields: { ...invitationTokenGuard, onboarding_complete: false, email: user.email },
        label: `Complete onboarding for ${user.email}`,
      });
      await emitRecordAutomation(base44, 'user_registered', saved.id, String(saved?.email || 'system'));
      return Response.json({ success: true, user: sanitizedUser(saved) });
    }

    return Response.json({ success: false, error: 'Invalid onboarding action' }, { status: 400 });
  } catch (error) {
    const status = Number(error?.status || 500);
    const safeStatus = [400, 401, 403, 404, 409, 429, 503].includes(status) ? status : 500;
    console.error('onboardingAccountAction error:', safeStatus, error?.message || error);
    return Response.json({ success: false, error: safeStatus === 500 ? 'Onboarding could not be completed safely' : error.message }, { status: safeStatus });
  }
});
